"""Self-contained interactive evidence viewer, measured points and trajectories."""
import html,os
from s07_common import *
from mapping_analysis import ply

def render(out,data):
    out=Path(out);points=ply(BASE/'maps/frozen/map_cloud.ply');points=points[::max(1,len(points)//18000)];cases={}
    for name,c in data['cases'].items():
        p=ROOT/c['path'];cases[name]=dict(evidence_base=os.path.relpath(p,out),metrics=c['metrics'],**read(p/'plot_data.json'))
    payload=json.dumps(dict(cases=cases,points=np.round(points,3).tolist(),manifest=verify_bundle(),contracts=data.get('contracts',{})),ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    content=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>S07 冻结地图与重启重定位</title>
<style>body{font:16px system-ui,sans-serif;background:#101b2b;color:#e8f0fa;margin:0;padding:28px;max-width:1480px;margin:auto}h1{font-size:30px;margin-bottom:8px}h2{font-size:20px}p{line-height:1.65;color:#bfcede}section{background:#19283c;border:1px solid #354960;border-radius:14px;padding:20px;margin:16px 0}.grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}canvas{width:100%;background:#102033;border-radius:8px}select,button{padding:8px;background:#2a405a;color:white;border:1px solid #6e859e;border-radius:6px;margin:4px}input{accent-color:#5ce0af}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:8px;border-bottom:1px solid #354960}.good{color:#65e4b1}.bad{color:#ffad88}a{color:#8dc8ff}code{overflow-wrap:anywhere;font-size:13px}#detail{white-space:pre-wrap;line-height:1.6}@media(max-width:1000px){.grid{display:block}} </style>
<h1>S07 · 冻结地图与重启重定位</h1><p>__STATUS__ · 数据来自真实 Gazebo / ROS 运行。用户人工验收：NOT_CHECKED。蓝色为固定地图，绿色为定位轨迹，橙色为独立评分真值；真值不输入在线定位。</p>
<section><label>试验 <select id="case"></select></label><label><input id="truth" type="checkbox" checked>显示评分真值</label><label><input id="focus" type="checkbox" checked>放大机器人附近</label><select id="view"><option value="top">俯视 XY</option><option value="3d">斜视三维点云</option></select><br>回放 <input id="time" type="range" min="0" max="100" value="100" style="width:65%"><span id="clock"></span></section>
<div class="grid"><section><canvas id="map" width="1000" height="700"></canvas><p>点云颜色随高度变化；空白表示没有可靠观测，不是可通行许可。坐标 map，单位 m。没有通过真值拟合对齐轨迹。</p></section><section><h2>当前证据</h2><div id="detail"></div><h2>状态与准入</h2><canvas id="timeline" width="480" height="230"></canvas><p>绿：可靠定位；黄：退化/重新确认；红：丢失；灰：初始化。最下一行为动作准入。拖动上方时间条检查故障前后。</p></section></div>
<section><h2>位置与航向误差（只统计获得许可的时刻）</h2><table id="metrics"><tr><th>案例</th><th>首获许可 s</th><th>XY RMSE m</th><th>航向 RMSE °</th><th>首次定位后准入比例</th><th>结论</th><th>原始证据</th></tr></table><p>门槛：XY RMSE &lt;1.5 m，航向 RMSE &lt;6°，首获许可 &lt;45 仿真秒。准入比例按首次可靠定位以后的全部时段计算，包含本轮故障；精度通过不表示连续定位可用率已经达到商用要求。这是包括 S06 地图偏差的绝对误差；不是对整张地图精度的保证。需粗略人工位置先验，不代表任意位置无先验全局定位。</p></section>
<section><h2>冻结地图与版本拒绝</h2><div id="binding"></div><table id="contracts"><tr><th>注入</th><th>实际拒绝原因</th><th>结果</th></tr></table><p>此处计划绑定是 DIAGNOSTIC_MOTION_FIXTURE；S12 真实计划需再次端到端验证。临时障碍不会写入只读长期地图。粗地形不等于可通行性判断。</p><a href="result.json">完整指标 / 命令</a> · <a href="browser_check.json">浏览器交互检查</a></section>
<script>const data=__DATA__;const $=id=>document.getElementById(id);const names=Object.keys(data.cases);for(const name of names){let o=document.createElement('option');o.textContent=name;o.value=name;$('case').append(o);let m=data.cases[name].metrics;let tr=document.createElement('tr');[name,m.first_localized_sim_s?.toFixed(2),m.xy_rmse_m?.toFixed(3),m.yaw_rmse_deg?.toFixed(3),m.admission_fraction_after_first_fix===undefined?'N/A':(100*m.admission_fraction_after_first_fix).toFixed(1)+'%',m.passed?'PASS':'FAIL'].forEach(x=>{let td=document.createElement('td');td.textContent=x??'N/A';tr.append(td)});let td=document.createElement('td');for(const file of ['metrics.json','runtime.json']){let a=document.createElement('a');a.textContent=file==='metrics.json'?'指标 ':'进程';a.href=data.cases[name].evidence_base+'/'+file;td.append(a)}tr.append(td);$('metrics').append(tr)}for(const c of data.contracts.cases||[]){let tr=document.createElement('tr');[c.name,c.reason,c.passed?'PASS':'FAIL'].forEach(x=>{let td=document.createElement('td');td.textContent=x;tr.append(td)});$('contracts').append(tr)}$('binding').textContent='只读地图 '+data.manifest.map_id+'；内容修订 '+data.manifest.revision;
function draw(){const canvas=$('map'),ctx=canvas.getContext('2d'),d=data.cases[$('case').value];ctx.clearRect(0,0,canvas.width,canvas.height);if(!d){ctx.fillStyle='white';ctx.fillText('此案例为离线版本准入检查，无仿真轨迹。',30,40);window.s07Rendered=true;return}const maxT=d.status.at(-1)?.t||1,t=Number($('time').value)/100*maxT,st=d.status.filter(x=>x.t<=t).at(-1),path=d.trajectory.filter(x=>x.t<=t),last=path.at(-1),center=$('focus').checked?(last?.truth||d.truth[0]?.xyz||[0,0,0]):[55,25,0],scale=$('focus').checked?36:6;const project=p=>{let x=p[0]-center[0],y=p[1]-center[1],z=p[2]||0;return $('view').value==='3d'?[500+scale*(x-.45*y),350-scale*(.65*y+z)]:[500+scale*x,350-scale*y]};ctx.fillStyle='#33435a';for(let x=0;x<1000;x+=scale*5){ctx.fillRect(x,0,1,700)}for(let y=0;y<700;y+=scale*5){ctx.fillRect(0,y,1000,1)}for(const p of data.points){let [x,y]=project(p);if(x<0||y<0||x>1000||y>700)continue;ctx.fillStyle=p[2]>.5?'#5c9ab9':'#294c66';ctx.fillRect(x,y,2,2)}function line(points,color){ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();points.forEach((p,i)=>{let q=project(p);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.stroke()}if($('truth').checked)line(d.truth.filter(x=>x.t<=t).map(x=>x.xyz),'#ffb472');line(path.map(x=>x.estimate),'#5ce0af');if(last){let p=project(last.estimate);ctx.fillStyle='#5ce0af';ctx.beginPath();ctx.arc(...p,7,0,7);ctx.fill()}ctx.fillStyle='white';ctx.font='16px sans-serif';ctx.fillText('map XY / m · 网格 5 m · 中心 '+center.slice(0,2).map(x=>x.toFixed(1)).join(', '),20,675);$('clock').textContent=t.toFixed(2)+' s';const q=d.evidence.filter(x=>x.received_t<=t).at(-1);$('detail').textContent=(st?st.state+'\n'+st.reason+'\n动作准入：'+st.navigation_allowed+'\n有效观测年龄：'+st.observation_age_s.toFixed(2)+' s\n连续确认：'+st.confirmation_count:'尚未启动')+(q?'\n表面重合比例：'+(100*q.surface_overlap).toFixed(1)+'%\n匹配点 P95：'+(q.surface_p95_m?.toFixed(3)??'N/A')+' m':'')+(last?'\n位置误差：'+last.xy_error_m.toFixed(3)+' m\n航向误差：'+last.yaw_error_deg.toFixed(3)+'°':'');const c=$('timeline').getContext('2d');c.clearRect(0,0,480,230);const colors={LOCALIZED:'#5ce0af',RELOCALIZING:'#f4ce77',DEGRADED:'#f4ce77',LOST:'#f28d83',INITIALIZING:'#8796a9'};for(let i=0;i<d.status.length-1;i++){let s=d.status[i],x=20+440*s.t/maxT,w=Math.max(1,440*(d.status[i+1].t-s.t)/maxT);c.fillStyle=colors[s.state];c.fillRect(x,25,w,60);c.fillStyle=s.navigation_allowed?'#5ce0af':'#624554';c.fillRect(x,120,w,35)}c.strokeStyle='white';c.beginPath();c.moveTo(20+440*t/maxT,10);c.lineTo(20+440*t/maxT,175);c.stroke();c.fillStyle='white';c.font='14px sans-serif';c.fillText('0 s',20,205);c.fillText(maxT.toFixed(0)+' s',420,205);window.s07Rendered=true}
for(const id of ['case','truth','focus','view'])$(id).addEventListener('change',draw);$('time').addEventListener('input',draw);draw();</script></html>'''
    (out/'index.html').write_text(content.replace('__STATUS__',html.escape(data['status'])).replace('__DATA__',payload))
